/**
 * Fan stories, one per goal, generated by matchdesk.domain.story_feed. Every fact in a story's
 * text comes from a claim the verifier passed; the page shows those checks and re-runs them.
 */
import feed from "./generated/nbr-riv-stories.json";

export type { Story, StoryClaim, StoryEvent, StorySummary, StoryText } from "./story-chrome";
import type { Story, StoryClaim, StorySummary } from "./story-chrome";

const data = feed as unknown as { stories: Story[]; claims: StoryClaim[]; replay_end_ms: number; match_id: string };

export const stories: readonly Story[] = data.stories;
export const storyMatchId = data.match_id;
export const storyReplayEndMs = data.replay_end_ms;

export function findStory(slug: string): Story | undefined {
  return stories.find((s) => s.slug === slug);
}

/** The claims one story cites, for display and for re-checking in the browser. */
export function storyClaims(story: Story): StoryClaim[] {
  const ids = new Set(story.checks.flatMap((c) => c.claim_ids));
  return data.claims.filter((c) => ids.has(c.claim_id));
}

export function storySummaries(): StorySummary[] {
  return stories.map((s) => ({
    slug: s.slug, team: s.team, scorer: s.scorer, clock: s.clock,
    headline: { en: s.text.fan.en.headline, es: s.text.fan.es.headline, fr: s.text.fan.fr.headline },
  }));
}

